package ro.leo.keypad;
public final class PersonalWordsTest {
 static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("check "+checks);}
 public static void main(String[] args){PersonalWords p=new PersonalWords();check(p.candidates("").isEmpty());check(!p.add("a"));check(!p.add("a@b.ro"));check(!p.add("123456"));check(p.add("Ștefănel"));check(p.candidates(PredictiveDictionary.digits("Ștefănel")).get(0).equals("ștefănel"));check(p.add("acasă"));check(p.add("acasă"));check(p.candidates("22272").get(0).equals("acasă"));String saved=p.save();PersonalWords q=new PersonalWords();q.load(saved);check(q.save().equals(saved));q.load("bad\tNaN\nvalid\t999999\ninvalid!\t1\n");check(q.words().size()==1);check(q.save().contains("999"));p.remove("ștefănel");check(!p.words().contains("ștefănel"));check(p.candidates("999999999999").get(0).equals("999999999999"));StringBuilder many=new StringBuilder();for(int i=0;i<400;i++)many.append("cuvant").append((char)('a'+i/26)).append((char)('a'+i%26)).append("\t1\n");p.load(many.toString());check(p.words().size()==256);check(!p.add("extracuvânt"));check(p.add(p.words().get(0)));System.out.println("Personal dictionary: "+checks+" checks passed");}
}
